<script setup lang="ts">
import { computed } from 'vue'
import { ArrowUpRight, CircleHelp } from 'lucide-vue-next'
import type { QualityIssueSummary, QualityCheckBatch, QualityIssueItem } from '../../api/admin/governance'
import { overviewSummary,groupOverviewTables,overviewCoverage,overviewStatuses,overviewStatusNames,type OverviewStatus } from '../../utils/governanceOverview'
const props=defineProps<{summary:QualityIssueSummary|null;rows:QualityIssueItem[];complete:boolean;aggregateLoading:boolean;message:string;issueLoading:boolean;issueError:string;canViewIssues:boolean;batch:QualityCheckBatch|null;batchLoading:boolean;batchError:string;batchState:string;batchDescription:string;batchScope:string}>()
const emit=defineEmits<{plot:[value:{status?:OverviewStatus;tableName?:string;issueDomain?:'SOURCE'|'SEMANTIC'}];help:[];coverage:[];retry:[];cancel:[]}>()
const model=computed(()=>overviewSummary(props.summary))
const groups=computed(()=>props.complete?groupOverviewTables(props.rows):[]),bars=computed(()=>groups.value.slice(0,8))
const axisMax=computed(()=>Math.max(2,Math.ceil(Math.max(0,...groups.value.map(g=>g.count))/2)*2))
const remainder=computed(()=>groups.value.slice(8).reduce((n,g)=>n+g.count,0))
const coverage=computed(()=>overviewCoverage(props.batch))
const coverageNames={SUCCESS:'执行成功',FAILURE:'失败',NOT_APPLICABLE:'不适用',NOT_EXECUTED:'未执行'} as const
const issueAvailable=computed(()=>props.canViewIssues&&!props.issueError&&!props.issueLoading&&model.value.total!=null)
const domainFraction=computed(()=>model.value.total&&model.value.domains?model.value.domains.SOURCE/model.value.total:0)
</script>
<template>
 <div class="overview-analysis" data-overview-charts>
  <div class="analysis-row">
   <figure class="main-figure"><figcaption class="figure-head"><h2>{{ complete?'未解决问题集中度':'当前处理结构' }}</h2><span>{{ model.total==null?'当前数量未知':`当前快照 ${model.total} 条 · 单位：条` }}</span></figcaption>
    <p v-if="!canViewIssues" class="emptyplot">没有此数据源的「查看质量问题」权限；无权不表示问题为0。</p>
    <p v-else-if="issueLoading" class="emptyplot" role="status">正在读取问题统计…</p>
    <p v-else-if="issueError" class="emptyplot" role="alert">{{ issueError }}</p>
    <p v-else-if="model.total===0" class="emptyplot"><strong>暂无待处理问题</strong>已读取范围确认0条；不代表来源质量或业务口径全部通过。</p>
    <p v-else-if="model.total==null" class="emptyplot">问题总数未确认，不推断为空。</p>
    <template v-else>
     <div class="status-legend" role="group" aria-label="按单个状态查看问题"><button v-for="status in overviewStatuses" :key="status" :disabled="!model.statuses" :aria-label="`查看${overviewStatusNames[status]}问题`" @click="emit('plot',{status})"><i :class="status" aria-hidden="true" />{{ overviewStatusNames[status] }} <b>{{ model.statuses?.[status] ?? '—' }}</b><ArrowUpRight :size="12" /></button><button class="status-help" aria-label="查看处理状态说明" title="此前已结束处理，现重新进入待确认流程；可能由人工重新开启，也可能由语义复查触发。" @click="emit('help')">状态说明 <CircleHelp :size="12" /></button></div>
     <template v-if="complete">
      <div class="table-bars" role="group" aria-label="按表和处理状态查看问题"><div v-for="group in bars" :key="group.name??'__unlocated__'" class="stack-row"><span class="tname" :title="group.name??'未定位表名'">{{ group.name??'未定位表名' }}</span><div class="bar-track"><template v-for="status in overviewStatuses" :key="status"><button v-if="group.statuses[status] && group.name!==null" class="bar-segment" :class="status" :style="{width:group.statuses[status]/axisMax*100+'%'}" :aria-label="`${group.name} ${overviewStatusNames[status]} ${group.statuses[status]}条，前往问题中心`" @click="emit('plot',{tableName:group.name,status})">{{ group.statuses[status]/axisMax>=.04 ? group.statuses[status] : '' }}</button><span v-else-if="group.statuses[status]" class="bar-segment" :class="status" :style="{width:group.statuses[status]/axisMax*100+'%'}" :aria-label="`未定位表名，${overviewStatusNames[status]}${group.statuses[status]}条`">{{ group.statuses[status]/axisMax>=.04?group.statuses[status]:'' }}</span></template></div><button v-if="group.name!==null" class="total-jump" :aria-label="`${group.name}共${group.count}条，选择状态`" @click="emit('plot',{tableName:group.name})">{{ group.count }}</button><span v-else class="total-jump">{{ group.count }}</span></div></div>
      <div class="axis" aria-hidden="true"><span/><div><span>0</span><span>{{ axisMax/2 }}</span><span>{{ axisMax }} 条</span></div><span/></div>
      <p class="figure-note">按本轮完整分页核对，非事务快照；{{ groups.length>8?`仅示前8组，另有${remainder}条未绘。`:'读取期间可能变化。' }}未定位表名不伪造成表筛选。</p>
     </template>
     <template v-else><div v-if="model.statuses" class="status-fallback"><button v-for="status in overviewStatuses" :key="status" class="fallback-row" @click="emit('plot',{status})"><span>{{ overviewStatusNames[status] }}</span><span class="track" aria-hidden="true"><i :class="status" :style="{width:model.statuses[status]/Math.max(1,...Object.values(model.statuses))*100+'%'}"/></span><b>{{ model.statuses[status] }}</b></button></div><p class="figure-note" :role="message?'status':undefined">{{ aggregateLoading?'正在取得完整明细，先展示权威状态摘要。':message || '表聚合未确认，不从最近几条问题推算总体。' }}</p><button v-if="aggregateLoading" class="evidence-link" @click="emit('cancel')">停止表聚合</button></template>
    </template>
   </figure>
   <figure class="domain-figure"><figcaption class="figure-head"><h2>问题来源构成</h2><span>SOURCE / SEMANTIC</span></figcaption><p v-if="!issueAvailable" class="emptyplot">{{ !canViewIssues?'无权读取问题分域，不按0显示。':issueLoading?'正在读取分域…':'分域统计不可用，不沿用旧比例。' }}</p><p v-else-if="model.total===0" class="emptyplot">已读取问题为0，不绘制空饼冒充健康评分。</p><p v-else-if="!model.domains" class="emptyplot">分域计数未核实；缺字段或合计不符时不推算。</p><template v-else><div class="domain-body"><svg class="donut" viewBox="0 0 128 128" role="img" :aria-label="`未解决${model.total}条，来源问题${model.domains.SOURCE}条，语义问题${model.domains.SEMANTIC}条`"><circle cx="64" cy="64" r="45" fill="none" stroke="var(--overview-semantic)" stroke-width="14"/><circle cx="64" cy="64" r="45" fill="none" stroke="var(--do-primary)" stroke-width="14" :stroke-dasharray="`${domainFraction*Math.PI*90} ${Math.PI*90}`" transform="rotate(-90 64 64)"/><text class="total" x="64" y="65" text-anchor="middle">{{ model.total }}</text><text class="label" x="64" y="85" text-anchor="middle">未解决问题</text></svg><div class="domain-labels"><button v-for="domain in (['SOURCE','SEMANTIC'] as const)" :key="domain" class="domain-jump" :aria-label="`${domain==='SOURCE'?'来源问题':'语义问题'}${model.domains[domain]}条，选择状态`" @click="emit('plot',{issueDomain:domain})"><span><i :class="domain" aria-hidden="true"/>{{ domain==='SOURCE'?'来源问题':'语义问题' }}</span><b>{{ model.domains[domain] }}</b></button></div></div><p class="figure-note">同一未解决集合的互斥分域，不是质量分或完成率。先选状态，再进入问题中心。</p></template></figure>
  </div>
  <figure class="coverage-figure"><figcaption class="coverage-title"><h2>来源校验执行覆盖 <span>{{ batchState }}</span></h2><span v-if="batch">最近批次 #{{ batch.id }} · {{ batchScope }}{{ coverage?` · ${coverage.total}条规则`:'' }}</span></figcaption><p v-if="batchLoading" class="emptyplot" role="status">正在读取校验状态…</p><p v-else-if="batchError" class="emptyplot" role="alert">{{ batchError }}</p><template v-else><p v-if="!batch || !coverage" class="emptyplot">{{ batchDescription }}{{ batch && !coverage ? '规则覆盖明细或分母未完整核实，不推算比例。':'' }}</p><div v-else class="coverage-bar" role="img" :aria-label="`本批次${coverage.total}条规则，${Object.entries(coverage.counts).map(([k,n])=>coverageNames[k as keyof typeof coverageNames]+n).join('、')}；执行成功不等于质量通过`"><div v-for="[status,n] in Object.entries(coverage.counts).filter(([,n])=>n>0)" :key="status" class="coverage-part" :class="status" :style="{width:n/coverage.total*100+'%'}">{{ coverageNames[status as keyof typeof coverageNames] }} <b>{{ n }}</b></div></div><p v-if="batch?.errorSummary" role="alert" class="batch-error">{{ batch.errorSummary }}</p><div class="coverage-foot"><span>分母为该批次规则数，非字段数量；执行成功不等于质量无问题。</span><span>{{ batch ? batch.complete ? '本批次完整性仍按范围核对' : 'complete=false · 不展示本次完整评分' : '无批次不推断历史从未执行' }}</span></div></template><button class="evidence-link" @click="emit('coverage')">查看执行依据 <ArrowUpRight :size="13" /></button></figure>
 </div>
</template>
<style scoped>
.overview-analysis{--overview-semantic:#5c7363;--overview-open:#a45c3b;--overview-confirmed:#95a690;--overview-reopened:#bd7470;border:1px solid var(--do-line);border-radius:10px;background:var(--do-surface);overflow:hidden}
.analysis-row{display:grid;grid-template-columns:1.42fr 1fr}.main-figure,.domain-figure{padding:20px 21px;margin:0;min-width:0}.domain-figure{border-left:1px solid var(--do-line)}.figure-head{display:flex;justify-content:space-between;gap:15px;align-items:baseline;margin-bottom:14px}.figure-head h2{font-size:15px;margin:0;font-weight:600;line-height:1.4}.figure-head>span{font-size:10px;color:var(--do-muted);white-space:nowrap}
button{font:inherit;cursor:pointer}button:focus-visible{outline:3px solid var(--do-primary);outline-offset:3px}button:disabled{cursor:not-allowed;color:var(--do-muted)}.status-legend{display:flex;gap:13px;margin-bottom:17px;align-items:center;flex-wrap:wrap}.status-legend button{border:0;background:none;color:var(--do-muted);font-size:10px;display:flex;gap:5px;align-items:center;padding:2px 0;min-height:24px}.status-legend i,.domain-jump i{display:inline-block;width:7px;height:7px;border-radius:2px}.OPEN{background:var(--overview-open)}.CONFIRMED{background:var(--overview-confirmed)}.REOPENED{background:var(--overview-reopened)}.status-legend b{color:var(--do-ink);font-weight:600}.status-help{margin-left:auto}.table-bars{display:grid;gap:11px}.stack-row{display:grid;grid-template-columns:83px minmax(0,1fr) 26px;gap:12px;align-items:center;min-height:24px}.tname{font:11px ui-monospace,Consolas,monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bar-track{display:flex;height:18px;border-radius:3px;overflow:hidden;background:var(--do-soft);gap:1px}.bar-segment{border:0;color:white;min-width:0;padding:0;font-size:10px;font-weight:500;line-height:18px;text-align:center}.bar-segment.CONFIRMED{color:#253121}.bar-segment.REOPENED{color:#241312}.bar-segment:focus-visible{outline:2px solid var(--do-ink);outline-offset:-3px}.total-jump{font-size:12px;font-weight:600;color:var(--do-ink);border:0;background:none;padding:3px 0;min-height:27px;text-align:right}.axis{display:grid;grid-template-columns:83px 1fr 26px;gap:12px;color:var(--do-muted);font-size:9px;margin-top:7px}.axis div{display:flex;justify-content:space-between}.figure-note{font-size:10px;color:var(--do-muted);line-height:1.8;margin:12px 0 0}.domain-body{display:flex;gap:19px;align-items:center;min-width:0;margin:8px 0 13px}.donut{width:125px;height:125px;flex-shrink:0}.donut text{font-family:inherit;fill:var(--do-ink)}.donut .total{font-size:29px;font-weight:600}.donut .label{font-size:10px;fill:var(--do-muted)}.domain-labels{display:grid;gap:9px;flex:1;min-width:0}.domain-jump{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:5px 0;border:0;background:none;text-align:left;color:var(--do-ink);font-size:11px}.domain-jump span{display:flex;align-items:center;gap:6px;white-space:nowrap}.domain-jump b{font-size:19px;font-weight:550}.domain-jump .SOURCE{background:var(--do-primary)}.domain-jump .SEMANTIC{background:var(--overview-semantic)}.emptyplot{padding:22px 0;color:var(--do-muted);font-size:12px;line-height:1.9}.emptyplot strong{display:block;color:var(--do-ink);font-size:14px;font-weight:550;margin-bottom:5px}.status-fallback{display:grid;gap:13px}.fallback-row{display:grid;grid-template-columns:80px 1fr 25px;gap:12px;align-items:center;font-size:11px;border:0;background:none;text-align:left;padding:3px 0}.track{height:12px;background:var(--do-soft);border-radius:2px;overflow:hidden}.track i{height:100%;display:block}.coverage-figure{margin:0;padding:18px 21px;border-top:1px solid var(--do-line);background:var(--do-soft)}.coverage-title{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:12px}.coverage-title h2{font-size:14px;font-weight:600;margin:0;display:flex;gap:10px;align-items:center}.coverage-title h2 span{font-weight:400;color:var(--do-warning);font-size:11px}.coverage-title>span{font-size:10px;color:var(--do-muted)}.coverage-bar{display:flex;height:31px;border-radius:4px;overflow:hidden;gap:2px}.coverage-part{display:flex;justify-content:center;align-items:center;gap:7px;font-size:10px;min-width:0}.coverage-part b{font-size:13px;font-weight:600}.coverage-part.SUCCESS{background:#c3d1bf;color:#263d2a}.coverage-part.FAILURE{background:#efd2cd;color:#7f352e}.coverage-part.NOT_APPLICABLE{background:#e6e8e0;color:#535c50}.coverage-part.NOT_EXECUTED{background:#e8ddc7;color:#69502d}.coverage-foot{display:flex;justify-content:space-between;gap:20px;font-size:10px;color:var(--do-muted);line-height:1.8;margin-top:10px}.evidence-link{display:flex;align-items:center;gap:6px;border:0;background:none;color:var(--do-muted);font-size:11px;padding:6px 0;margin-top:5px}.batch-error{font-size:12px;color:var(--do-danger);line-height:1.8}
</style>
